mapper.select:
SELECT id, task_id, skill_name, hit_type, platform, title, summary,
       dedupe_key, payload_json, source_tool, tool_event_id,
       created_at, updated_at
FROM xw_task_hit
WHERE task_id = #{taskId}

    AND hit_type = #{hitType}


    AND platform = #{platform}

ORDER BY id ASC
LIMIT #{limit}
